                max_row = j

        # Swap rows
        rref[i], rref[max_row] = rref[max_row], rref[i]

        # Eliminate below pivot
        for j in range(i + 1, rows):
            factor = Fraction(rref[j][i], rref[i][i])
            for k in range(cols):
